def transform(grid):
    from collections import Counter
    g = [r[:] for r in grid]
    H, W = len(g), len(g[0])
    cnt = Counter(v for r in g for v in r)
    bg = cnt.most_common(1)[0][0]
    divider = None
    for c in range(W):
        colset = {g[r][c] for r in range(H)}
        if len(colset) == 1:
            v = colset.pop()
            if v != bg:
                divider = c
                break
    dv = g[0][divider] if divider is not None else None
    oc, best = None, 0
    for v, n in cnt.items():
        if v != bg and v != dv and n > best:
            best, oc = n, v
    cells = [(r, c) for r in range(H) for c in range(W) if g[r][c] == oc]
    minc = min(c for _, c in cells)
    maxc = max(c for _, c in cells)
    if maxc < divider:
        shift = (divider - 1) - maxc
        lc = minc + shift - 1
    else:
        shift = (divider + 1) - minc
        lc = maxc + shift + 1
    for r, c in cells:
        g[r][c] = bg
    for r, c in cells:
        g[r][c + shift] = oc
    for r in range(H):
        g[r][lc] = 8
    return g
